func windowSum(_ arr: [Int], k: Int) -> Int {
    var sum = 0
    for i in 0..<k { sum += arr[i] }
    var maxS = sum
    for i in k..<arr.count {
        sum += arr[i] - arr[i - k]
        if sum > maxS { maxS = sum }
    }
    return maxS
}
print(windowSum([1, 4, 2, 10, 2], k: 2))

