func reverseArrayInPlace(_ numbers: inout [Int]) {
    var left = 0
    var right = numbers.count - 1
    while left < right {
        numbers.swapAt(left, right)
        left += 1
        right -= 1
    }
}
var arr = [1, 2, 3, 4, 5]
reverseArrayInPlace(&arr)
print(arr)

func isPalindromeWord(_ word: String) -> Bool {
    let chars = Array(word.lowercased())
    var left = 0
    var right = chars.count - 1
    while left < right {
        if chars[left] != chars[right] {
            return false
        }
        left += 1
        right -= 1
    }
    return true
}
print(isPalindromeWord("radar"))

func maxConsecutiveSum(_ numbers: [Int], k: Int) -> Int {
    guard numbers.count >= k, k > 0 else { return 0 }
    var currentSum = 0
    for i in 0..<k {
        currentSum += numbers[i]
    }
    var maxSum = currentSum
    for i in k..<numbers.count {
        currentSum += numbers[i] - numbers[i - k]
        if currentSum > maxSum {
            maxSum = currentSum
        }
    }
    return maxSum
}
print(maxConsecutiveSum([1, 2, 3, 4, 5], k: 2))
